def dilate8(a):
 z=np.zeros_like(a)
 for r in range(4):
  for c in range(4):
   z[r,c]=any(a[i,j] for i in range(max(0,r-1),min(4,r+2)) for j in range(max(0,c-1),min(4,c+2)) if (i,j)!=(r,c))
 return z
