from collections import deque
def bfsdist(seeds,blocked,allow=None):
 d=np.full((4,4),999,int); q=deque()
 for r,c in np.argwhere(seeds): d[r,c]=0;q.append((r,c))
 while q:
  r,c=q.popleft()
  for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
   if 0<=rr<4 and 0<=cc<4 and not blocked[rr,cc] and d[rr,cc]==999:
    d[rr,cc]=d[r,c]+1;q.append((rr,cc))
 return d
